package project.init.account.utils;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;public class Encoder {    private static final BCryptPasswordEncoder encoder = new BCryptPasswordEncoder();    public static boolean base64CheckPassword(String account, String password, String passwordHash) {        return encoder.matches(account.toUpperCase() + password, passwordHash);    }    public static String base64Encrypt(String account, String password) {        return encoder.encode(account.toUpperCase() + password);    }}